import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"DIDLab","text":"Blockchain engineering, by shipping","tagline":"Six labs. You extend a working dApp, prove it with tests, and get it through review — the way the job actually works.","actions":[{"theme":"brand","text":"Start with lab 1","link":"/labs/lab-1-shipping-your-first-change"},{"theme":"alt","text":"Read the module guides","link":"/modules/"},{"theme":"alt","text":"Open Trustville","link":"https://dapp.didlab.org"}]},"features":[{"title":"A real codebase, not exercises","details":"Twenty-two contracts and a React frontend, deployed and running. Every lab is a change to it — a spec, acceptance criteria, and a pull request that has to survive review."},{"title":"Marked on how it fails","details":"A quarter of the grade is failure states. Rejected in the wallet, reverted on chain, wrong network, stale data. Anyone can write the happy path."},{"title":"Honest about the limits","details":"Every module says where a plain database would have been better, and what it did not fix. One contract ships a deliberate vulnerability, with a test that exploits it."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1790431304000}'),n={name:"index.md"};function o(r,e,h,l,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h2 id="what-this-is" tabindex="-1">What this is <a class="header-anchor" href="#what-this-is" aria-label="Permalink to &quot;What this is&quot;">​</a></h2><p>Trustville is a small town where each everyday trust problem is solved with a blockchain feature — a registry, a soulbound passport, escrow, a sealed-bid auction, verifiable certificates, deeds, a DAO treasury, an oracle-fed insurer, an exchange with lending. Fifteen modules, live on a real chain.</p><p>You will use it once, in week one. After that it is the codebase you work in.</p><h2 id="the-two-questions-behind-every-module" tabindex="-1">The two questions behind every module <a class="header-anchor" href="#the-two-questions-behind-every-module" aria-label="Permalink to &quot;The two questions behind every module&quot;">​</a></h2><p><strong>When would a plain database have been better?</strong> Most of these problems have a boring solution that is faster and cheaper, and a good engineer can say which. Every module guide argues both sides, because a developer who only knows when to reach for a chain is a liability.</p><p><strong>What did this module not fix?</strong> The chain can prove a certificate has not been altered. It has no idea whether your degree is real. Knowing exactly where the guarantee stops is most of the skill.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><p>You need Node 20+, Foundry, git, and MetaMask with a wallet made for this course. Then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/touidhasan/didlab-trustville</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> didlab-trustville</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local</span></span></code></pre></div><p>That gives you a private Trustville on your own machine: your own chain, all 22 contracts, the site pointed at it. No faucet, no permissions, nothing you do touches anyone else.</p><p>If that command does not give you a working town, stop and fix it — that is lab 0, and nobody skips it.</p><h2 id="where-to-read" tabindex="-1">Where to read <a class="header-anchor" href="#where-to-read" aria-label="Permalink to &quot;Where to read&quot;">​</a></h2><p>The <strong><a href="/modules/">module guides</a></strong> explain the town: one guide per module, each one taking a trust problem apart and then saying what the contract failed to solve. Read the guide for a module before you touch its code.</p><p>The <strong><a href="/labs/">labs</a></strong> are the graded work. They assume you have read the guide.</p><p><a href="/modules/">The module guides →</a> · <a href="/labs/">The labs →</a></p>`,15)])])}const g=a(n,[["render",o]]);export{c as __pageData,g as default};
